/* Serves the Forecast Builder single-page app.
 * The HTML is stored as a JSON-encoded string literal so nothing inside it
 * (quotes, backticks, ${...}, Arabic text) can break out and corrupt the node.
 * RespondToWebhook sends it with Content-Type: text/html.
 */
const HTML = "<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Legend Sleep — Forecast Builder</title>
<style>
  :root{--navy:#0F3D5E;--orange:#F18F01;--teal:#2E86AB;--line:#dde7ef;--bg:#f2f6f9;--ink:#22333f;--mute:#6b8496}
  *{box-sizing:border-box}
  body{margin:0;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:var(--bg);color:var(--ink)}
  header{background:var(--navy);color:#fff;padding:14px 20px;display:flex;align-items:center;gap:14px;position:sticky;top:0;z-index:20}
  header h1{font-size:16px;margin:0;font-weight:600;letter-spacing:-.01em}
  header .month{margin-left:auto;font-size:13px;opacity:.85}
  .steps{display:flex;gap:6px;padding:12px 20px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:50px;z-index:19}
  .steps b{font-weight:600;font-size:12px;padding:5px 12px;border-radius:20px;background:#eef4f8;color:var(--mute)}
  .steps b.on{background:var(--navy);color:#fff}
  .steps b.done{background:#e3f3e8;color:#1f7a3d}
  main{padding:20px;max-width:1180px;margin:0 auto}
  .card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:16px}
  h2{font-size:15px;margin:0 0 4px;color:var(--navy)}
  .hint{color:var(--mute);font-size:13px;margin:0 0 16px}
  label{display:block;font-weight:600;font-size:12px;color:var(--navy);margin:12px 0 5px}
  input[type=text],input[type=number],select,textarea{width:100%;padding:9px 11px;border:1px solid var(--line);border-radius:8px;font:inherit;background:#fff}
  input:focus,select:focus,textarea:focus{outline:2px solid var(--teal);outline-offset:-1px}
  textarea{font-family:ui-monospace,Menlo,monospace;font-size:13px;min-height:90px}
  button{font:inherit;font-weight:600;border:0;border-radius:8px;padding:10px 18px;cursor:pointer}
  .primary{background:var(--orange);color:#fff}.primary:hover{background:#d87f00}
  .primary:disabled{background:#c9d6df;cursor:not-allowed}
  .ghost{background:#eef4f8;color:var(--navy)}.ghost:hover{background:#e0ebf2}
  .row{display:flex;gap:12px;flex-wrap:wrap}.row>*{flex:1;min-width:180px}
  .drop{border:2px dashed #c6d7e3;border-radius:12px;padding:34px;text-align:center;color:var(--mute);background:#fafcfd;cursor:pointer}
  .drop.hot{border-color:var(--orange);background:#fff8ee;color:var(--navy)}
  .drop b{color:var(--navy)}
  .toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}
  .toolbar input[type=text]{flex:1;min-width:200px}
  .chip{padding:6px 13px;border-radius:20px;background:#eef4f8;color:var(--mute);font-size:12px;font-weight:600;cursor:pointer;border:1px solid transparent;white-space:nowrap}
  .chip.on{background:var(--teal);color:#fff}
  .tablewrap{border:1px solid var(--line);border-radius:10px;overflow:auto;max-height:56vh;background:#fff}
  table{width:100%;border-collapse:collapse;font-size:13px}
  thead th{position:sticky;top:0;background:#f7fafc;text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--mute);z-index:2}
  tbody td{padding:6px 10px;border-bottom:1px solid #f0f5f8;vertical-align:middle}
  tbody tr.has{background:#fff8ee}
  tbody tr:hover{background:#f7fbfd}
  .ar{direction:rtl;text-align:right;font-size:13px}
  .num{text-align:right;font-variant-numeric:tabular-nums;color:var(--mute)}
  .qty{width:78px;padding:5px 7px;text-align:right;border:1px solid var(--line);border-radius:6px;font:inherit;font-variant-numeric:tabular-nums}
  .qty.set{border-color:var(--orange);font-weight:600;color:var(--navy)}
  .exp{background:none;border:0;color:var(--mute);cursor:pointer;font-size:15px;padding:2px 6px;border-radius:5px}
  .exp:hover{background:#e8f0f5;color:var(--navy)}
  .exp.on{color:var(--orange)}
  tr.weeks td{background:#fbfdfe;padding:10px 12px}
  .wk{display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap}
  .wk div{display:flex;flex-direction:column;gap:3px}
  .wk span{font-size:10px;font-weight:700;color:var(--mute);letter-spacing:.05em}
  .wk input{width:74px;padding:5px 7px;text-align:right;border:1px solid var(--line);border-radius:6px;font:inherit}
  .wk input.edited{border-color:var(--orange);font-weight:600}
  .wk .note{font-size:11px;color:var(--mute);align-self:center;max-width:230px}
  .bar{position:sticky;bottom:0;background:#fff;border-top:2px solid var(--navy);padding:12px 20px;display:flex;gap:22px;align-items:center;flex-wrap:wrap;font-size:13px}
  .bar b{color:var(--navy);font-variant-numeric:tabular-nums}
  .bar .sp{margin-left:auto;display:flex;gap:10px}
  .pill{background:#eef4f8;border-radius:7px;padding:5px 10px;font-size:12px;font-variant-numeric:tabular-nums}
  .warn{background:#fff8ee;border-left:4px solid var(--orange);padding:11px 14px;border-radius:8px;font-size:13px;margin:12px 0}
  .err{background:#fdecec;border-left:4px solid #d33;padding:11px 14px;border-radius:8px;font-size:13px;margin:12px 0;white-space:pre-wrap;font-family:ui-monospace,Menlo,monospace}
  .ok{background:#e9f7ee;border-left:4px solid #1f7a3d;padding:11px 14px;border-radius:8px;font-size:13px;margin:12px 0}
  .hide{display:none!important}
  .spin{display:inline-block;width:14px;height:14px;border:2px solid #fff6;border-top-color:#fff;border-radius:50%;animation:s .7s linear infinite;vertical-align:-2px;margin-right:7px}
  @keyframes s{to{transform:rotate(360deg)}}
  .empty{padding:30px;text-align:center;color:var(--mute)}
  @media (prefers-color-scheme:dark){
    :root{--bg:#0e1a22;--ink:#dce7ee;--line:#26404f;--mute:#8fa9ba}
    body{background:var(--bg)} .card,.tablewrap,table,.bar,.steps{background:#132430}
    thead th{background:#162c3a} tbody td{border-bottom-color:#1d3543}
    input,select,textarea,.qty,.wk input{background:#0e1a22;color:var(--ink)}
    tbody tr.has{background:#2a2114} tbody tr:hover{background:#17303e}
    tr.weeks td{background:#102030} .drop{background:#102030}
  }
</style>

<header>
  <h1>📊 Legend Sleep — Forecast Builder</h1>
  <div class="month" id="hdrMonth"></div>
</header>

<div class="steps">
  <b id="s1" class="on">1 · Workbook</b>
  <b id="s2">2 · Products</b>
  <b id="s3">3 · Marketing spend</b>
  <b id="s4">4 · Download</b>
</div>

<main>
  <!-- ---------------------------------------------------------------- 1 -->
  <section id="scr1">
    <div class="card">
      <h2>Start from your current workbook</h2>
      <p class="hint">Your file is the template — you get it back with the same 11 tabs, formulas and charts, just new numbers. It is never modified in place. The product list below is read from <i>your</i> file, so it is always up to date.</p>
      <div class="drop" id="drop">
        <b>Click to choose your .xlsx</b><br>or drag it here
        <div id="fileName" style="margin-top:9px;font-weight:600;color:var(--orange)"></div>
      </div>
      <input type="file" id="file" accept=".xlsx" class="hide">
      <div class="row">
        <div>
          <label for="month">Report month</label>
          <input type="text" id="month" placeholder="2026-08" pattern="\d{4}-\d{2}">
        </div>
        <div>
          <label for="chan">Default channel</label>
          <select id="chan">
            <option value="ONLINE | إلكتروني">ONLINE — إلكتروني</option>
            <option value="BRANCHES | فروع">BRANCHES — فروع</option>
            <option value="Both | كلاهما">Both — كلاهما</option>
          </select>
        </div>
      </div>
      <div id="err1"></div>
      <div style="margin-top:16px"><button class="primary" id="go1" disabled>Read my workbook →</button></div>
    </div>
  </section>

  <!-- ---------------------------------------------------------------- 2 -->
  <section id="scr2" class="hide">
    <div class="card" style="padding-bottom:12px">
      <h2>Pick products and enter monthly quantities</h2>
      <p class="hint">Search by Arabic name or SKU. Type a monthly quantity — it splits across the five weeks automatically (24 / 15 / 11 / 20 / 30&nbsp;%). Click <b>⌄</b> on a row only if you want to set individual weeks by hand.</p>
      <div class="toolbar">
        <input type="text" id="q" placeholder="🔍  Search product name or SKU…">
        <span class="chip on" data-cat="">All</span>
        <span class="chip" data-cat="Royal Boxes">Royal Boxes</span>
        <span class="chip" data-cat="Mattresses">Mattresses</span>
        <span class="chip" data-cat="Mattress Toppers">Toppers</span>
        <span class="chip" data-cat="Pillows">Pillows</span>
        <span class="chip" data-cat="Comforter Sets">Comforters</span>
        <span class="chip" id="onlyPicked">Only picked</span>
      </div>
      <div class="tablewrap">
        <table>
          <thead><tr>
            <th style="width:92px">SKU</th><th>Product</th><th style="width:120px">Category</th>
            <th style="width:96px" class="num">Price</th><th style="width:120px">Channel</th>
            <th style="width:96px">Qty / month</th><th style="width:34px"></th>
          </tr></thead>
          <tbody id="tb"></tbody>
        </table>
        <div class="empty hide" id="noRows">No products match that search.</div>
      </div>
    </div>
    <div class="bar">
      <span>Picked <b id="nPick">0</b></span>
      <span>Units <b id="nUnits">0</b></span>
      <span class="pill" id="wkTot">W1 0 · W2 0 · W3 0 · W4 0 · W5 0</span>
      <span>Revenue <b id="nRev">0</b> SAR</span>
      <div class="sp">
        <button class="ghost" id="back2">← Back</button>
        <button class="primary" id="go2" disabled>Next — marketing spend →</button>
      </div>
    </div>
  </section>

  <!-- ---------------------------------------------------------------- 3 -->
  <section id="scr3" class="hide">
    <div class="card">
      <h2>Marketing spend</h2>
      <p class="hint">All optional. Leave everything blank to keep the spend already in your workbook untouched. Amounts in SAR — convert foreign currency first.</p>
      <label for="spTotal">Total for the month (split 24/15/11/20/30 automatically)</label>
      <input type="number" id="spTotal" placeholder="e.g. 500000" min="0" step="any">
      <label>…or set each week by hand (these win over the total)</label>
      <div class="row" id="spWeeks"></div>
      <label for="spLines">…or detailed lines — <code>category, platform, amount</code> (these win over everything)</label>
      <textarea id="spLines" placeholder="Influencers, Influencer, 50000&#10;Paid Digital Marketing, TikTok, 120000"></textarea>
      <div class="warn" id="roasBox"></div>
      <div id="err3"></div>
      <div style="margin-top:6px;display:flex;gap:10px">
        <button class="ghost" id="back3">← Back to products</button>
        <button class="primary" id="go3">Generate my workbook</button>
      </div>
    </div>
  </section>

  <!-- ---------------------------------------------------------------- 4 -->
  <section id="scr4" class="hide">
    <div class="card">
      <h2 id="doneTitle">Building…</h2>
      <div id="doneBody"></div>
      <div style="margin-top:16px"><button class="ghost" id="again">Start another forecast</button></div>
    </div>
  </section>
</main>

<script>
const WEIGHTS=[.24,.15,.11,.20,.30], WK=['W1','W2','W3','W4','W5'], VAT=0.15;
const $=id=>document.getElementById(id);
let FILE=null, PRODUCTS=[], PICK=new Map(), CAT='', PICKED_ONLY=false;

/* ---------------------------------------------------------- screen 1 */
$('drop').onclick=()=>$('file').click();
['dragover','dragenter'].forEach(e=>$('drop').addEventListener(e,ev=>{ev.preventDefault();$('drop').classList.add('hot')}));
['dragleave','drop'].forEach(e=>$('drop').addEventListener(e,ev=>{ev.preventDefault();$('drop').classList.remove('hot')}));
$('drop').addEventListener('drop',ev=>{ if(ev.dataTransfer.files[0]) setFile(ev.dataTransfer.files[0]); });
$('file').onchange=e=>{ if(e.target.files[0]) setFile(e.target.files[0]); };
function setFile(f){
  if(!f.name.toLowerCase().endsWith('.xlsx')){ $('err1').innerHTML='<div class="err">That is not an .xlsx file.</div>'; return; }
  FILE=f; $('err1').innerHTML=''; $('fileName').textContent='📄 '+f.name+'  ('+(f.size/1024|0)+' KB)';
  check1();
}
const d=new Date(); $('month').value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
$('month').oninput=check1;
function check1(){ $('go1').disabled=!(FILE && /^\d{4}-\d{2}$/.test($('month').value.trim())); }
check1();

$('go1').onclick=async()=>{
  const b=$('go1'); b.disabled=true; b.innerHTML='<span class="spin"></span>Reading your workbook…';
  try{
    const fd=new FormData(); fd.append('action','catalog'); fd.append('file',FILE);
    const r=await fetch(location.pathname,{method:'POST',body:fd});
    const t=await r.text();
    let j; try{ j=JSON.parse(t); }catch(e){ throw new Error(t.slice(0,600)); }
    if(!r.ok||j.error) throw new Error(j.error||t.slice(0,600));
    PRODUCTS=j.products||[];
    if(!PRODUCTS.length) throw new Error('No products found in the Pricelist tab of that file.');
    render(); show(2);
  }catch(e){ $('err1').innerHTML='<div class="err">'+esc(e.message)+'</div>'; }
  finally{ b.disabled=false; b.textContent='Read my workbook →'; check1(); }
};

/* ---------------------------------------------------------- screen 2 */
$('q').oninput=render;
document.querySelectorAll('.chip[data-cat]').forEach(c=>c.onclick=()=>{
  document.querySelectorAll('.chip[data-cat]').forEach(x=>x.classList.remove('on'));
  c.classList.add('on'); CAT=c.dataset.cat; render();
});
$('onlyPicked').onclick=()=>{ PICKED_ONLY=!PICKED_ONLY; $('onlyPicked').classList.toggle('on',PICKED_ONLY); render(); };

function autoSplit(q){ return WEIGHTS.map(w=>q*w); }
function rowOf(sku){ return PICK.get(sku); }

function render(){
  const q=$('q').value.trim().toLowerCase();
  const list=PRODUCTS.filter(p=>{
    if(CAT && p.category!==CAT) return false;
    if(PICKED_ONLY && !(rowOf(p.sku)?.qty>0)) return false;
    if(!q) return true;
    return p.sku.toLowerCase().includes(q) || (p.name||'').toLowerCase().includes(q);
  });
  const tb=$('tb'); tb.innerHTML='';
  $('noRows').classList.toggle('hide',list.length>0);
  const frag=document.createDocumentFragment();
  for(const p of list){
    const st=rowOf(p.sku);
    const tr=document.createElement('tr');
    if(st?.qty>0) tr.className='has';
    tr.innerHTML='<td style="font-variant-numeric:tabular-nums;color:var(--mute)">'+esc(p.sku)+'</td>'+
      '<td class="ar">'+esc(p.name||'—')+'</td>'+
      '<td style="font-size:12px;color:var(--mute)">'+esc(p.category||'<span style="color:#c60">— set in sheet</span>')+'</td>'+
      '<td class="num">'+(p.price!=null?fmt(p.price):'—')+'</td>'+
      '<td></td><td></td><td></td>';
    // channel
    const sel=document.createElement('select');
    sel.style.cssText='padding:4px 6px;font-size:12px;border-radius:6px';
    [['','default'],['ONLINE | إلكتروني','ONLINE'],['BRANCHES | فروع','BRANCHES'],['Both | كلاهما','Both']]
      .forEach(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;sel.appendChild(o)});
    sel.value=st?.channel||'';
    sel.onchange=()=>{ ensure(p.sku).channel=sel.value; totals(); };
    tr.children[4].appendChild(sel);
    // qty
    const qi=document.createElement('input');
    qi.type='number'; qi.min='0'; qi.step='any'; qi.className='qty'+(st?.qty>0?' set':'');
    qi.value=st?.qty??''; qi.placeholder='0';
    qi.oninput=()=>{
      const s=ensure(p.sku); s.qty=qi.value===''?0:Number(qi.value);
      if(!s.manual) s.weeks=autoSplit(s.qty);
      qi.classList.toggle('set',s.qty>0); tr.classList.toggle('has',s.qty>0);
      const wr=tr.nextElementSibling;
      if(wr&&wr.classList.contains('weeks')) fillWeeks(wr,p.sku);
      totals();
    };
    tr.children[5].appendChild(qi);
    // expander
    const ex=document.createElement('button');
    ex.className='exp'+(st?.manual?' on':''); ex.textContent='⌄'; ex.title='Set individual weeks';
    ex.onclick=()=>toggleWeeks(tr,p.sku,ex);
    tr.children[6].appendChild(ex);
    frag.appendChild(tr);
    if(st?.open){ const wr=weekRow(p.sku); frag.appendChild(wr); fillWeeks(wr,p.sku); ex.classList.add('on'); }
  }
  tb.appendChild(frag); totals();
}
function ensure(sku){
  if(!PICK.has(sku)) PICK.set(sku,{qty:0,weeks:[0,0,0,0,0],manual:false,channel:'',open:false});
  return PICK.get(sku);
}
function weekRow(sku){
  const tr=document.createElement('tr'); tr.className='weeks';
  const td=document.createElement('td'); td.colSpan=7;
  td.innerHTML='<div class="wk"></div>'; tr.appendChild(td); tr.dataset.sku=sku; return tr;
}
function fillWeeks(tr,sku){
  const s=ensure(sku), box=tr.querySelector('.wk'); box.innerHTML='';
  WK.forEach((w,i)=>{
    const d=document.createElement('div');
    d.innerHTML='<span>'+w+'</span>';
    const inp=document.createElement('input');
    inp.type='number'; inp.min='0'; inp.step='any';
    inp.value=round3(s.weeks[i]); if(s.manual) inp.classList.add('edited');
    inp.oninput=()=>{ s.manual=true; s.weeks[i]=inp.value===''?0:Number(inp.value);
      s.qty=s.weeks.reduce((a,b)=>a+b,0);
      const qi=tr.previousElementSibling.querySelector('.qty'); qi.value=round3(s.qty); qi.classList.add('set');
      tr.previousElementSibling.classList.add('has');
      box.querySelectorAll('input').forEach(x=>x.classList.add('edited'));
      totals(); };
    d.appendChild(inp); box.appendChild(d);
  });
  const n=document.createElement('div'); n.className='note';
  n.textContent=s.manual?'Manual — these exact numbers are used.':'Auto-split. Editing any week switches this row to manual.';
  box.appendChild(n);
  const rb=document.createElement('button'); rb.className='ghost'; rb.style.cssText='padding:6px 11px;font-size:12px';
  rb.textContent='Reset to auto';
  rb.onclick=()=>{ s.manual=false; s.weeks=autoSplit(s.qty); fillWeeks(tr,sku); totals(); };
  box.appendChild(rb);
}
function toggleWeeks(tr,sku,ex){
  const s=ensure(sku); const nx=tr.nextElementSibling;
  if(nx&&nx.classList.contains('weeks')){ nx.remove(); s.open=false; ex.classList.toggle('on',s.manual); }
  else{ s.open=true; const wr=weekRow(sku); tr.after(wr); fillWeeks(wr,sku); ex.classList.add('on'); }
}
function totals(){
  let n=0,u=0,rev=0; const w=[0,0,0,0,0];
  for(const [sku,s] of PICK){
    if(!(s.qty>0)) continue;
    n++; const mult=(s.channel||$('chan').value).startsWith('Both')?1:1;
    u+=s.qty*mult; s.weeks.forEach((v,i)=>w[i]+=v);
    const p=PRODUCTS.find(x=>x.sku===sku); if(p&&p.price!=null) rev+=s.qty*p.price;
  }
  $('nPick').textContent=n; $('nUnits').textContent=fmt(u);
  $('wkTot').textContent=WK.map((k,i)=>k+' '+fmt(w[i])).join(' · ');
  $('nRev').textContent=fmt(rev);
  $('go2').disabled=n===0;
  window.__rev=rev;
}
$('back2').onclick=()=>show(1);
$('go2').onclick=()=>{ spendUI(); show(3); };

/* ---------------------------------------------------------- screen 3 */
function spendUI(){
  if($('spWeeks').children.length) { roas(); return; }
  WK.forEach(w=>{
    const d=document.createElement('div');
    d.innerHTML='<label for="sp'+w+'">'+w+'</label><input type="number" min="0" step="any" id="sp'+w+'" placeholder="optional">';
    $('spWeeks').appendChild(d);
  });
  ['spTotal','spLines',...WK.map(w=>'sp'+w)].forEach(id=>$(id).oninput=roas);
  roas();
}
function spendNow(){
  const lines=$('spLines').value.trim();
  if(lines) return lines.split(/\n/).map(l=>Number(l.split(',').pop())||0).reduce((a,b)=>a+b,0);
  const per=WK.map(w=>Number($('sp'+w).value)||0);
  if(per.some(v=>v>0)) return per.reduce((a,b)=>a+b,0);
  return Number($('spTotal').value)||0;
}
function roas(){
  const spend=spendNow(), before=(window.__rev||0)/(1+VAT);
  $('roasBox').innerHTML = spend>0
    ? '<b>Forecast ROAS '+(before/spend).toFixed(2)+'×</b> — revenue before VAT '+fmt(before)+' SAR ÷ spend '+fmt(spend)+' SAR.'
      +(before/spend<20?' <span style="color:#c60">Below the 20× target.</span>':' ✅ Meets the 20× target.')
      +'<br><span style="font-size:12px;color:var(--mute)">Note: this compares <i>all</i> forecast revenue against this spend. If your spend is online-only, the online-only figure is the more meaningful one.</span>'
    : 'Enter spend to see forecast ROAS. Leave blank to keep whatever spend is already in your workbook.';
}
$('back3').onclick=()=>show(2);
$('go3').onclick=build;

/* ---------------------------------------------------------- build */
function forecastLines(){
  const out=[];
  for(const [sku,s] of PICK){
    if(!(s.qty>0)) continue;
    const ch=s.channel?', '+s.channel:'';
    out.push(s.manual ? sku+', '+s.weeks.map(v=>round3(v)).join(',')+ch
                      : sku+', '+round3(s.qty)+ch);
  }
  return out.join('\n');
}
async function build(){
  show(4); $('doneTitle').textContent='Building your workbook…';
  $('doneBody').innerHTML='<div class="hint"><span class="spin" style="border-color:#0003;border-top-color:var(--navy)"></span>Writing rows, recalculating formulas…</div>';
  try{
    const payload={reportMonth:$('month').value.trim(),defaultChannel:$('chan').value,
